<?php
declare(strict_types=1);
$basePath=dirname(__DIR__);require $basePath.'/vendor/autoload.php';
use Modulon\Core\Modules\ModuleManifestReader;
try{$root=$argv[1]??'';$manifest=(new ModuleManifestReader())->read($root.'/module.json');foreach($manifest->psr4 as $prefix=>$relative){spl_autoload_register(static function(string $class)use($prefix,$root,$relative):void{if(str_starts_with($class,$prefix)){$file=$root.'/'.rtrim($relative,'/').'/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($file))require $file;}});}$entry=$root.'/'.$manifest->entryFile;if(!is_file($entry))throw new RuntimeException('Entrypoint-Datei fehlt.');require_once $entry;if(!class_exists($manifest->entryClass,false))throw new RuntimeException('Entrypoint-Klasse wurde nicht definiert.');if(method_exists($manifest->entryClass,'healthCheck')){$result=$manifest->entryClass::healthCheck();if($result!==true)throw new RuntimeException(is_string($result)?$result:'Modul meldet unhealthy.');}echo json_encode(['ok'=>true,'message'=>'Entrypoint isoliert geladen.'],JSON_THROW_ON_ERROR).PHP_EOL;exit(0);}catch(Throwable $e){echo json_encode(['ok'=>false,'message'=>$e->getMessage()],JSON_UNESCAPED_SLASHES).PHP_EOL;exit(1);}
